// Etsy sales: read-only aggregation. Output has buyer first name only; never addresses, emails, tracking, carrier, notes or drafts.
const TZ = "America/New_York";
let items = [];
try { items = $("Notion Etsy Orders").all(); } catch (e) { items = []; }
const rows = items.map(i => i && i.json).filter(j => j && j.id); // drops alwaysOutputData placeholders
const props = p => (p && typeof p.properties === "object" && p.properties) || {};
const text = v => !v ? "" : Array.isArray(v.title) ? v.title.map(t => (t && t.plain_text) || "").join("") : Array.isArray(v.rich_text) ? v.rich_text.map(t => (t && t.plain_text) || "").join("")
  : v.select ? (v.select.name || "") : v.status ? (v.status.name || "") : "";
const find = (p, re) => { const pr = props(p); for (const k in pr) if (re.test(k)) return pr[k]; return null; };
const str = (p, re) => String(text(find(p, re))).trim();
const numOf = v => { // number property, else rich text / title like "$1,234.50"; null when unusable
  if (!v) return null;
  if (typeof v.number === "number" && Number.isFinite(v.number)) return v.number;
  const s = text(v).replace(/[^0-9.\-]/g, "");
  if (!/\d/.test(s)) return null;
  const n = parseFloat(s); return Number.isFinite(n) ? n : null;
};
const round2 = n => Math.round(n * 100) / 100;

const fmt = new Intl.DateTimeFormat("en-CA", { timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", hourCycle: "h23" });
const parts = t => { const o = {}; for (const x of fmt.formatToParts(new Date(t))) o[x.type] = x.value; return o; };
const ymdOf = t => { const o = parts(t); return o.year + "-" + o.month + "-" + o.day; };
const addDays = (ymd, n) => { const [y, m, d] = ymd.split("-").map(Number); return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10); };
const midnight = ymd => { // instant of 00:00 America/New_York on ymd
  const [y, m, d] = ymd.split("-").map(Number); const base = Date.UTC(y, m - 1, d);
  for (const h of [4, 5, 6]) { const t = base + h * 3600000; const o = parts(t); if (o.year + "-" + o.month + "-" + o.day === ymd && Number(o.hour) === 0) return t; }
  return base + 5 * 3600000;
};
const nowMs = Date.now();
const today = ymdOf(nowMs);
const hi = midnight(addDays(today, 1));
const lo7 = midnight(addDays(today, -6)), lo30 = midnight(addDays(today, -29)); // [lo, hi), today included

const toMs = s => { // ISO string -> ms; date-only means midnight New York; null when unusable
  if (typeof s !== "string" || !s) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) { const t = Date.parse(s + "T00:00:00Z"); return Number.isNaN(t) ? null : midnight(s); }
  const t = Date.parse(s); return Number.isNaN(t) ? null : t;
};
const dateMs = (p, re) => { const v = find(p, re); return v && v.date ? toMs(v.date.start) : null; };
const dayOf = ms => (ms === null ? null : ymdOf(ms));

const STATUSES = ["New", "Packed", "Shipped", "Delivered", "Issue"];
const by_status = {}; for (const s of STATUSES) by_status[s] = 0;
const tot = { orders_7d: 0, revenue_7d: 0, orders_30d: 0, revenue_30d: 0 };
const currencies = new Set();
const toShip = [], recent = [];
for (const p of rows) {
  const status = str(p, /^status$/i);
  if (STATUSES.includes(status)) by_status[status]++;
  const cur = str(p, /^currency$/i).toUpperCase().slice(0, 8);
  if (cur) currencies.add(cur);
  const orderId = str(p, /^order id$/i).slice(0, 60);
  const total = numOf(find(p, /^total$/i));
  const odMs = dateMs(p, /^order date$/i);
  if (odMs !== null) {
    if (odMs >= lo30 && odMs < hi) { tot.orders_30d++; tot.revenue_30d += total || 0; }
    if (odMs >= lo7 && odMs < hi) { tot.orders_7d++; tot.revenue_7d += total || 0; }
    recent.push({ order: orderId, date: dayOf(odMs), total: total === null ? null : round2(total), status: status, ms: odMs });
  }
  if (status === "New" || status === "Packed") {
    const sbMs = dateMs(p, /^ship by$/i);
    const shipBy = dayOf(sbMs);
    toShip.push({
      order: orderId,
      buyer_first_name: str(p, /^buyer first name$/i).split(/\s+/)[0].slice(0, 60),
      items: str(p, /^items summary$/i).replace(/\s+/g, " ").slice(0, 200),
      ship_by: shipBy,
      overdue: shipBy !== null && shipBy < today,
    });
  }
}
toShip.sort((a, b) => (a.ship_by === null) - (b.ship_by === null) || (a.ship_by || "").localeCompare(b.ship_by || "") || a.order.localeCompare(b.order));
recent.sort((a, b) => b.ms - a.ms || a.order.localeCompare(b.order));
const currency = currencies.size === 0 ? null : currencies.size === 1 ? [...currencies][0] : "MIXED";
const totals = { orders_7d: tot.orders_7d, revenue_7d: round2(tot.revenue_7d), orders_30d: tot.orders_30d, revenue_30d: round2(tot.revenue_30d),
  avg_order_30d: tot.orders_30d ? round2(tot.revenue_30d / tot.orders_30d) : 0 };
return [{ json: { body: {
  generated_at: new Date(nowMs).toISOString(), currency, totals, by_status,
  to_ship: toShip.slice(0, 20),
  recent: recent.slice(0, 10).map(r => ({ order: r.order, date: r.date, total: r.total, status: r.status })),
  issues: by_status.Issue,
} } }];
